import Foundation

/// A narrow factual check, not a semantic correctness guarantee. Weekday names
/// come from macOS locale data rather than a translation generated by the model.
public enum TranslationCalendarGuard {
    private static func names(_ language: String) -> [[String]] {
        let formatter = DateFormatter()
        formatter.calendar = Calendar(identifier: .gregorian)
        formatter.locale = Locale(identifier: language)
        return zip(formatter.weekdaySymbols, formatter.standaloneWeekdaySymbols).map {
            Array(Set([$0.0, $0.1])).sorted { $0.count > $1.count }
        }
    }

    private static func counts(_ text: String, names: [[String]]) -> [Int] {
        names.map { aliases in
            let alternatives = aliases.map { name -> String in
                let escaped = NSRegularExpression.escapedPattern(for: name)
                // CJK dates join surrounding words without spaces.
                if name.range(of: "[\\p{Han}\\p{Hiragana}\\p{Katakana}]", options: .regularExpression) != nil { return escaped }
                return "(?<![\\p{L}\\p{M}])" + escaped + "(?![\\p{L}\\p{M}])"
            }.joined(separator: "|")
            guard let regex = try? NSRegularExpression(pattern: alternatives, options: [.caseInsensitive]) else { return 0 }
            return regex.numberOfMatches(in: text, range: NSRange(text.startIndex..., in: text))
        }
    }

    public static func preservesWeekdays(_ original: String, _ translated: String, source: String, target: String) -> Bool {
        let expected = counts(original, names: names(source))
        guard expected.contains(where: { $0 > 0 }) else { return true }
        return expected == counts(translated, names: names(target))
    }

    public static func instruction(_ text: String, source: String, target: String) -> String {
        let from = names(source), to = names(target)
        let present = counts(text, names: from)
        let mappings = present.indices.filter { present[$0] > 0 }.map { "\(from[$0][0]) = \(to[$0][0])" }
        return mappings.isEmpty ? "" : "Preserve these exact calendar weekdays: " + mappings.joined(separator: "; ") + ". Never substitute a different day."
    }
}
